CREATE OR REPLACE FUNCTION public.protect_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user='authenticated' THEN NEW.referral_code:=OLD.referral_code; NEW.referred_by:=OLD.referred_by; NEW.email:=OLD.email; NEW.marketplace_blocked:=OLD.marketplace_blocked; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.enforce_market_listing() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND marketplace_blocked) AND NEW.status='open' THEN RAISE EXCEPTION 'Marketplace access suspended'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_market_listing BEFORE INSERT OR UPDATE ON public.p2p_listings FOR EACH ROW EXECUTE FUNCTION public.enforce_market_listing();
CREATE OR REPLACE FUNCTION public.moderate_coin_listing(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l record; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admins only'; END IF; SELECT * INTO l FROM public.p2p_listings WHERE id=_id FOR UPDATE; IF l.status='open' THEN UPDATE public.p2p_listings SET status='removed' WHERE id=l.id; INSERT INTO public.ledger_entries(user_id,account,amount,kind,reference) VALUES(l.user_id,'p2p_escrow',-l.mvt_amount,'p2p_cancel','REMOVE-'||l.id||'-escrow'),(l.user_id,l.source_account,l.mvt_amount,'p2p_cancel','REMOVE-'||l.id||'-refund'); END IF; END $$;
REVOKE ALL ON FUNCTION public.moderate_coin_listing(uuid) FROM public,anon; GRANT EXECUTE ON FUNCTION public.moderate_coin_listing(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.nft_inventory() RETURNS TABLE(nft_id uuid,sold bigint,reserved bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT n.id,count(p.id) FILTER(WHERE p.status='success'),count(p.id) FILTER(WHERE p.status='pending' AND p.quote_expires_at>now()) FROM public.nfts n LEFT JOIN public.payments p ON p.nft_id=n.id WHERE n.active OR public.has_role(auth.uid(),'admin') GROUP BY n.id $$;
REVOKE ALL ON FUNCTION public.nft_inventory() FROM public,anon; GRANT EXECUTE ON FUNCTION public.nft_inventory() TO authenticated;